import CREATURES from "@heroesofcrypto/common/src/configuration/creatures.json";
import { getPositionForCell } from "@heroesofcrypto/common/src/grid/grid_math";
import {
    AttackVals,
    ToFactionName,
    type AttackHandler,
    type Grid,
    type TeamType,
    type Unit,
} from "@heroesofcrypto/common";

export const JOINT_DELIVERY_UTILITY_ID = "a19-joint-contact-shooting-utility-v1";

/**
 * Research proxy, not predicted damage or a win probability. The native contact utility already
 * weights a stack by XP/1000. Put retained shooting on that same scale, using real projected attack
 * and the engine's exact range bands. Enemy deployment, defenses, randomness and incoming attacks
 * are deliberately absent. Twelve hypothetical cells match the native contact target set.
 */
export function jointDeliveryShootingUtility(
    units: readonly Unit[],
    grid: Grid,
    handler: AttackHandler,
    team: TeamType,
) {
    const settings = grid.getSettings();
    const catalog = CREATURES as unknown as Record<string, Record<string, { attack: number }>>;
    const rows = [];
    for (const unit of units) {
        if (unit.getTeam() !== team) throw new Error("Joint delivery utility received another team's unit");
        if (unit.getAttackType() !== AttackVals.RANGE || unit.getRangeShots() <= 0) continue;
        const printedAttack = catalog[ToFactionName[unit.getFaction()]]?.[unit.getName()]?.attack;
        if (!printedAttack || !Number.isFinite(printedAttack)) throw new Error("Missing printed ranged attack");
        const divisors = [];
        for (const x of team === 2 ? [12, 13, 14] : [1, 2, 3])
            for (const y of [3, 6, 9, 12]) {
                const target = getPositionForCell(
                    { x, y },
                    settings.getMinX(),
                    settings.getStep(),
                    settings.getHalfStep(),
                );
                divisors.push(handler.getRangeAttackDivisor(unit, target));
            }
        const xpWeight = (unit.getAmountAlive() * unit.getExp()) / 1000;
        const attackRatio = Math.max(0, unit.getAttack()) / printedAttack;
        const coverage = divisors.reduce((sum, divisor) => sum + 1 / divisor, 0) / divisors.length;
        const score = xpWeight * attackRatio * coverage;
        if (![xpWeight, attackRatio, coverage, score].every(Number.isFinite))
            throw new Error("Nonfinite joint utility");
        rows.push({
            name: unit.getName(),
            amount: unit.getAmountAlive(),
            xpWeight,
            printedAttack,
            attack: unit.getAttack(),
            shotDistance: unit.getRangeShotDistance(),
            divisors,
            coverage,
            score,
        });
    }
    return { score: rows.reduce((sum, row) => sum + row.score, 0), rows };
}

