    type Unit,
} from "@heroesofcrypto/common";
import CREATURES from "@heroesofcrypto/common/src/configuration/creatures.json";
import { getPositionForCell } from "@heroesofcrypto/common/src/grid/grid_math";
import { jointDeliveryShootingUtility } from "./frozen-server/src/api/game/v1/joint_delivery_utility_score";
import { validateOutcome } from "./frozen-server/src/simulation/ai_iteration/identity";
import adapter from "./adapter";

const read = (name: string) => JSON.parse(readFileSync(`${import.meta.dir}/${name}`, "utf8"));
const settings = new GridSettings(16, 2048, 0, 1024, -1024, 0, 0);
const grid = { getSettings: () => settings } as Grid;
const handler = {
    getRangeAttackDivisor: AttackHandler.prototype.getRangeAttackDivisor.bind({
        gridSettings: settings,
    } as unknown as AttackHandler),
} as AttackHandler;
function shooter({ team = 2, distance = 4.9, attack = 10, sniper = false, farsight = false } = {}) {
    const catalog = CREATURES as unknown as Record<string, Record<string, { attack: number }>>;
    const faction = Number(Object.entries(ToFactionName).find(([, name]) => catalog[name]?.Orc)?.[0]);
    const printed = catalog[ToFactionName[faction]]!.Orc!.attack;
    return {
        getTeam: () => team,
        getName: () => "Orc",
        getFaction: () => faction,
        getAttackType: () => AttackVals.RANGE,
        getRangeShots: () => 9,
        getAmountAlive: () => 100,
        getExp: () => 10,
        getAttack: () => (printed * attack) / 10,
        getRangeShotDistance: () => distance,
        getPosition: () =>
            getPositionForCell(
                { x: team === 2 ? 1 : 14, y: 6 },
                settings.getMinX(),
                settings.getStep(),
                settings.getHalfStep(),
            ),
        getFootprintWidth: () => 1,
        getFootprintHeight: () => 1,
        hasAbilityActive: (name: string) => sniper && name === "Sniper",
        hasBuffActive: (name: string) => farsight && name === "Farsight Quiver",
    } as unknown as Unit;
}
test("projection uses the native whole-cell bands, attack bonuses, and range-ignore contracts", () => {
    const score = (unit: Unit) => jointDeliveryShootingUtility([unit], grid, handler, unit.getTeam());
    const low = score(shooter({ distance: 4.1 })),
        high = score(shooter({ distance: 4.9 }));
    expect(low.score).toBe(high.score);
    expect(low.rows[0].divisors).toEqual(high.rows[0].divisors);
    expect(score(shooter({ distance: 5 })).score).toBeGreaterThan(score(shooter()).score);
    expect(score(shooter({ attack: 12.7 })).score / score(shooter()).score).toBeCloseTo(1.27, 12);
    expect(score(shooter({ sniper: true })).score).toBe(1);
    expect(score(shooter({ farsight: true })).score).toBe(1);
    expect(score(shooter({ sniper: true, attack: 12.7 })).score).toBeCloseTo(1.27, 12);
    const right = score(shooter({ team: 1 })),
        left = score(shooter({ team: 2 }));
    expect(right.score).toBe(left.score);
    expect([...right.rows[0].divisors].sort()).toEqual([...left.rows[0].divisors].sort());
    expect(() => jointDeliveryShootingUtility([shooter({ team: 1 })], grid, handler, 2)).toThrow("another team's unit");
});
test("both complete native and qualified-guard outcomes retain their admitted controls exactly", async () => {
    const c = read("known-activation-case.json"),
        controls = read("known-activation-controls.json");
    for (const mode of ["current", "protect-entrant"]) {
        const input = await adapter.prepare(c, { id: mode, parameters: { mode } });
        const result = await adapter.execute(input);
        validateOutcome(result);
        expect(result).toEqual(controls.find((row: any) => row.arm === mode).execution.outcome);
    }
}, 120000);
test("joint utility actually runs inside the native funded setup and preserves preview state", async () => {
    const c = read("known-activation-case.json");
    const input = await adapter.prepare(c, { id: "joint-entrant", parameters: { mode: "joint-entrant" } });
    const result = await adapter.execute(input);
    validateOutcome(result);
    expect(result.qualityErrors).toEqual([]);
    expect(result.decisions).toBeGreaterThan(0);
    expect(result.diagnostics.previewRngUuidChecks).toBe(result.diagnostics.deliveryPreviewCalls);
    expect(result.diagnostics.leftSetupSpend).toBeLessThanOrEqual(result.diagnostics.leftSetupBudget);
    expect(result.diagnostics.rightSetupSpend).toBeLessThanOrEqual(result.diagnostics.rightSetupBudget);
    const events = (result.evidence as any).jointDeliveryPreviews;
    expect(events.length).toBeGreaterThan(1);
    for (const event of events) {
        expect(event.team).toBe(c.input.candidateTeam);
        expect(event.shooting.rows.length).toBeGreaterThan(0);
        expect(event.shooting.score).toBeGreaterThan(0);
        expect(event.joint).toBe(event.contact + event.shooting.score);
        expect(event.augments.reduce((sum: number, a: any) => sum + a.value, 0)).toBe(
            c.input.candidateTeam === 2 ? result.diagnostics.leftSetupBudget : result.diagnostics.rightSetupBudget,
        );
        for (const row of event.shooting.rows) {
            expect(row.divisors).toHaveLength(12);
            expect(row.divisors.every((value: number) => [1, 2, 4, 8].includes(value))).toBe(true);
        }
    }
}, 120000);
test("a consumed exclusive-delivery budget cannot activate either setup experiment", async () => {
    const c = read("known-activation-case.json");
    c.input.game.leftDeliveryDraftOverrideUsed = true;
    c.input.game.rightDeliveryDraftOverrideUsed = true;
    const current = await adapter.prepare(c, { id: "current", parameters: { mode: "current" } });
    for (const mode of ["protect-entrant", "joint-entrant"])
        expect(await adapter.prepare(c, { id: mode, parameters: { mode } })).toEqual(current);
});

