import assert from "node:assert/strict";
import { readFileSync, writeFileSync } from "node:fs";
import adapter from "./adapter";
import { executionKey, executionRuntimeKey } from "./frozen-server/src/simulation/ai_iteration/identity";
import type { IterationSeal } from "./frozen-server/src/simulation/ai_iteration/types";
const seal = JSON.parse(readFileSync(`${import.meta.dir}/seal.json`, "utf8")) as IterationSeal;
const runtimeKey = executionRuntimeKey(seal), rows = [];
for (const testCase of seal.plan.development) {
    let currentRanked: unknown;
    for (const arm of seal.plan.arms) {
        const input = await adapter.prepare(testCase, arm) as any;
        if (arm.id === "current") currentRanked = input.ranked;
        assert.deepEqual(input.ranked, currentRanked);
        assert.deepEqual(input.freeTeams, []);
        assert.deepEqual(input.protectTeams, arm.id === "protect-entrant" ? [input.ranked.candidateTeam] : []);
        assert.deepEqual(input.jointTeams, arm.id === "joint-entrant" ? [input.ranked.candidateTeam] : []);
        rows.push({ caseId: testCase.id, arm: arm.id, input, key: executionKey(runtimeKey, input) });
    }
}
writeFileSync(`${import.meta.dir}/prepared-bank-audit.json`, JSON.stringify({ runtimeKey, rows }, null, 2) + "\n");
console.log(JSON.stringify({ prepared: rows.length, allThreeArmsKeepIdenticalRankedInputs: true,
    actualCandidateTeamOnly: true, noScoreOrOutcomeUsed: true }));
